    "note": "グッチオ・グッチがサヴォイ・ホテルで働いていた話は有名ですが、ホテル側に記録がないとする指摘もあります。白いジャージーのドレスは1996年春夏とする資料と1996-97年秋冬とする資料があります。ジャンニーニの退任は2015年1月で、最後に手がけたのは2015年春夏とする資料もあります。"
